"""Where each part goes: the first layout and what makes a layout legal.

A layout is a state the search can change one step at a time:

- the *skeleton* (connectors, active parts, series two-pins) sits at
  absolute positions, columns left to right in signal order, inputs on the
  left edge and outputs on the right;
- every *attachment* (a shunt) is held relative to the pin it hangs from:
  its own pin on that net sits ``dx, dy`` grid steps from the host pin's
  end, at first straight out along the host pin. Moving a part moves what
  hangs off it, so the search never tears a capacitor away from its IC.
"""
from __future__ import annotations

import math
from dataclasses import dataclass, field
from typing import Optional

from eda_agent.design import sch_template as st

from .circuit import (DIRS, DOWN, GRID, LEFT, OUTLINE_MARGIN, RIGHT, UP, Attachment,
                      Circuit, Part, rotated_box)

Cell = tuple[int, int]


@dataclass
class State:
    skeleton: dict[str, tuple[int, int, int]]          # ref -> (x, y, orientation), mils
    attached: dict[str, tuple[int, int, int]]          # ref -> (anchor index, dx, dy)

    def copy(self) -> "State":
        return State(dict(self.skeleton), dict(self.attached))


@dataclass
class Placed:
    ref: str
    x: int
    y: int
    rotation: int
    pins: list[st.PinEnd]
    body: set[Cell]
    lines: set[Cell]          # pin lines, body side to wire end (end excluded)
    ends: dict[Cell, str]     # pin wire ends -> pin number
    halo: set[Cell]
    text: set[Cell]
    #: The part's outline as Altium reports it (BoundingRectangle: graphics
    #: and pins, plus a margin), in mils; design_audit_schematic calls two
    #: parts whose outlines meet an overlap.
    outline: tuple[int, int, int, int] = (0, 0, 0, 0)


@dataclass
class Layout:
    parts: dict[str, Placed]
    violations: int
    bounds: tuple[int, int, int, int] = (0, 0, 0, 0)     # cells, text included

    def pins(self) -> dict[str, list[st.PinEnd]]:
        return {ref: p.pins for ref, p in self.parts.items()}


def cell(x: int, y: int) -> Cell:
    return (x // GRID, y // GRID)


def _box_cells(x0: int, y0: int, x1: int, y1: int) -> set[Cell]:
    """Grid points inside a box, edges included."""
    return {(cx, cy)
            for cx in range(math.ceil(x0 / GRID), math.floor(x1 / GRID) + 1)
            for cy in range(math.ceil(y0 / GRID), math.floor(y1 / GRID) + 1)}


def _text_cells(ref: str, value: str, pins: list[st.PinEnd]) -> set[Cell]:
    """Where the preview writes the designator and value (st.text_boxes)."""
    box = st.body_box(pins)
    if not box:
        return set()
    x0, y0, x1, y1 = box
    out: set[Cell] = set()
    for text, (ty0, ty1) in ((ref, (y1, y1 + 100)), (value, (y0 - 100, y0))):
        if not text:
            continue
        tx0, tx1 = x1 + 20, x1 + 20 + 50 * len(text)
        # Every grid point whose square the text covers by more than a
        # sliver: a text between two rows of the grid still claims them.
        for cx in range(math.floor(tx0 / GRID) - 1, math.ceil(tx1 / GRID) + 2):
            for cy in range(math.floor(ty0 / GRID) - 1, math.ceil(ty1 / GRID) + 2):
                ox = min(tx1, cx * GRID + GRID // 2) - max(tx0, cx * GRID - GRID // 2)
                oy = min(ty1, cy * GRID + GRID // 2) - max(ty0, cy * GRID - GRID // 2)
                if ox > 15 and oy > 15:
                    out.add((cx, cy))
    return out


def anchors_for(c: Circuit, att: Attachment, skeleton: set[str]) -> list[tuple[str, str]]:
    """The pins an attachment may hang from: its net's pins on skeleton parts,
    active parts first (a decoupling capacitor belongs at the IC), then series
    parts, then connectors."""
    rank = {"active": 0, "one": 1, "two": 1, "connector": 2}
    pins = [(r, n) for (r, n) in c.nets[att.net].pins if r in skeleton and r != att.ref]
    return sorted(pins, key=lambda rn: (rank.get(c.parts[rn[0]].kind, 3), rn[0], rn[1]))


@dataclass
class Plan:
    """What stays fixed while the search runs: who is skeleton, who hangs where."""
    circuit: Circuit
    attachments: dict[str, Attachment]
    anchors: dict[str, list[tuple[str, str]]]
    skeleton: list[str]
    columns: dict[str, int] = field(default_factory=dict)
    rotations: dict[str, tuple[int, ...]] = field(default_factory=dict)


def make_plan(c: Circuit) -> Plan:
    atts = {ref: a for ref in c.parts if (a := c.attachment(ref)) is not None}
    skeleton = [ref for ref in c.parts if ref not in atts]
    anchors: dict[str, list[tuple[str, str]]] = {}
    for ref, a in list(atts.items()):
        cands = anchors_for(c, a, set(skeleton))
        if not cands:
            # Nothing on its net to hang from (a net of shunts only): it
            # stands on its own.
            del atts[ref]
            skeleton.append(ref)
        else:
            anchors[ref] = cands
    plan = Plan(c, atts, anchors, skeleton)
    plan.rotations = {ref: _allowed_rotations(c, ref) for ref in skeleton}
    plan.columns = _columns(plan)
    return plan


def _allowed_rotations(c: Circuit, ref: str) -> tuple[int, ...]:
    """Connectors face into the sheet (a free one either way); a two-pin
    part in a path may lie either way round, across or upright; everything
    else stands as its symbol was drawn."""
    part = c.parts[ref]
    if part.kind == "connector":
        # Per way it may face, one orientation, mirrored when that gives the
        # better pin order: a rail's pin on top, ground's at the bottom,
        # otherwise pin 1 on top. On the right edge only a mirrored part
        # faces in with pin 1 on top. The order is decided here, not
        # searched: searching it spread the same budget over twice the
        # choices and drafted looser sheets.
        first = str(part.symbol.pins[0].get("designator", ""))
        wants = {"left": (RIGHT,), "right": (LEFT,)}.get(part.side, (RIGHT, LEFT))
        rots = []
        for w in wants:
            cands = part.orientations_facing(first, w)
            if cands:
                rots.append(max(cands, key=lambda o: (_rails_in_order(c, part, o),
                                                      _pin_one_up(part, o), -o)))
        return tuple(rots) or (0,)
    if part.kind == "two":
        return (0, 90, 180, 270)
    return (0,)


def _signal_neighbours(plan: Plan, kinds: tuple[str, ...]) -> dict[str, set[str]]:
    c = plan.circuit
    sk = set(plan.skeleton)
    out: dict[str, set[str]] = {r: set() for r in plan.skeleton}
    for net in c.nets.values():
        if net.kind not in kinds:
            continue
        refs = {r for r, _ in net.pins if r in sk}
        for r in refs:
            out[r] |= refs - {r}
    return out


def main_part(plan: Plan) -> str:
    """The part the sheet is drawn around: the active part with most pins."""
    c = plan.circuit
    return max(plan.skeleton, key=lambda r: (c.parts[r].kind == "active",
                                             len(c.parts[r].symbol.pins), r))


def _columns(plan: Plan) -> dict[str, int]:
    """Columns, left to right, the way the pins lead: from the main part, a
    part met through a pin that points left goes one column left, through a
    pin that points right one column right, through a pin pointing up or
    down in the same column; a part in a path passes the direction on.
    Input connectors take the left edge, output connectors the right."""
    c = plan.circuit
    sk = plan.skeleton
    if not sk:
        return {}
    fixed = {r for r in sk if c.parts[r].kind == "connector" and c.parts[r].side}
    main = main_part(plan)
    col: dict[str, int] = {main: 0}
    heading: dict[str, int] = {main: 1}

    def step(u: str, pin: str) -> int:
        part = c.parts[u]
        if part.kind == "two":
            return heading.get(u, 1)
        facing = part.pin_offset(pin, plan.rotations[u][0])[2]
        return {RIGHT: 1, LEFT: -1}.get(facing, 0)

    for kinds in (("signal",), ("signal", "power")):
        queue = sorted(col, key=lambda r: col[r])
        while queue:
            u = queue.pop(0)
            for pin, net in sorted(c.nets_of(u).items()):
                if c.nets[net].kind not in kinds:
                    continue
                for v, _ in c.nets[net].pins:
                    if v == u or v not in heading and v not in sk or v in col or v in fixed:
                        continue
                    if v not in sk:
                        continue
                    d = step(u, pin)
                    col[v] = col[u] + d
                    heading[v] = d or heading.get(u, 1)
                    queue.append(v)
    for r in sk:
        if r not in col and r not in fixed:
            col[r] = 1
    lo = min(col.values())
    hi = max(col.values())
    for r in sorted(fixed):
        col[r] = lo - 1 if c.parts[r].side == "left" else hi + 1
    lo = min(col.values())
    return {r: k - lo for r, k in col.items()}


def realize(plan: Plan, state: State) -> Layout:
    c = plan.circuit
    placed: dict[str, Placed] = {}

    def put(ref: str, x: int, y: int, rot: int) -> None:
        part = c.parts[ref]
        pins = part.pin_ends(x, y, rot)
        bx0, by0, bx1, by1 = rotated_box(part.symbol.body(), rot)
        body = _box_cells(x + bx0, y + by0, x + bx1, y + by1)
        lines: set[Cell] = set()
        ends: dict[Cell, str] = {}
        for p in pins:
            end = cell(p.x, p.y)
            ends[end] = p.number
            dx, dy = DIRS[p.orientation]
            n = max(0, (abs(p.x - p.root_x) + abs(p.y - p.root_y)) // GRID)
            for i in range(n):
                lines.add(cell(p.root_x + dx * GRID * i, p.root_y + dy * GRID * i))
        lines -= set(ends)
        body -= set(ends)
        halo = {(a + i, b + j) for (a, b) in body for i in (-1, 0, 1) for j in (-1, 0, 1)}
        # Altium's outline: the graphics as drawn, and each pin with a
        # margin round it (measured on a placed diode and terminal block).
        m = OUTLINE_MARGIN
        xs = [x + bx0, x + bx1] + [q + s for p in pins for q in (p.x, p.root_x) for s in (-m, m)]
        ys = [y + by0, y + by1] + [q + s for p in pins for q in (p.y, p.root_y) for s in (-m, m)]
        placed[ref] = Placed(ref, x, y, rot, pins, body, lines, ends, halo,
                             _text_cells(ref, part.value, pins),
                             (min(xs), min(ys), max(xs), max(ys)))

    for ref, (x, y, rot) in state.skeleton.items():
        put(ref, x, y, rot)
    for ref, (ai, ox_, oy_) in state.attached.items():
        att = plan.attachments[ref]
        anchor_ref, anchor_pin = plan.anchors[ref][ai % len(plan.anchors[ref])]
        host = placed[anchor_ref]
        pe = next(p for p in host.pins if p.number == anchor_pin)
        tx = pe.x + ox_ * GRID
        ty = pe.y + oy_ * GRID
        part = c.parts[ref]
        rot = part.rotation_facing(att.lane_pin, att.lane_facing)
        if rot is None:
            rot = 90
        ox, oy, _ = part.pin_offset(att.lane_pin, rot)
        put(ref, tx - ox, ty - oy, rot)
    return Layout(placed, _violations(c, placed), _bounds(placed))


def _bounds(placed: dict[str, Placed]) -> tuple[int, int, int, int]:
    cells = [q for p in placed.values() for q in (p.body | p.lines | set(p.ends) | p.text)]
    if not cells:
        return (0, 0, 0, 0)
    xs = [q[0] for q in cells]
    ys = [q[1] for q in cells]
    return (min(xs), min(ys), max(xs), max(ys))


def _violations(c: Circuit, placed: dict[str, Placed]) -> int:
    """How many pairs of parts sit on each other or touch. Text is not a
    reason to refuse a placement: where Altium writes a designator is only
    estimated, so the checker's text_overlap warnings are scored instead."""
    items = list(placed.values())
    bad = 0
    for i, a in enumerate(items):
        core_a = a.body | a.lines | set(a.ends)
        for b in items[i + 1:]:
            core_b = b.body | b.lines | set(b.ends)
            shared = core_a & core_b
            if shared:
                ok = all(q in a.ends and q in b.ends
                         and c.pin_net.get((a.ref, a.ends[q])) is not None
                         and c.pin_net.get((a.ref, a.ends[q])) == c.pin_net.get((b.ref, b.ends[q]))
                         for q in shared)
                if not ok:
                    bad += 1
                    continue
            if a.halo & b.body or b.halo & a.body:
                bad += 1
    return bad


# --- the first layout ----------------------------------------------------------


def _extent(plan: Plan, ref: str, rot: int) -> tuple[int, int, int, int]:
    """A part's cells relative to its origin: (x0, y0, x1, y1) in cells."""
    one = realize_one(plan, ref, 0, 0, rot)
    cells = one.body | one.lines | set(one.ends) | one.text
    xs = [q[0] for q in cells]
    ys = [q[1] for q in cells]
    return (min(xs), min(ys), max(xs), max(ys))


def realize_one(plan: Plan, ref: str, x: int, y: int, rot: int) -> Placed:
    lay = realize(plan, State({ref: (x, y, rot)}, {}))
    return lay.parts[ref]


def _series_rotation(plan: Plan, ref: str, col: dict[str, int]) -> int:
    """A series part reads left to right: the pin toward the earlier column left."""
    c = plan.circuit
    part = c.parts[ref]
    rots = plan.rotations[ref]
    nets = c.nets_of(ref)
    score: dict[int, float] = {}
    for r in rots:
        s = 0.0
        for num, net in nets.items():
            ox, _, _ = part.pin_offset(num, r)
            others = [col.get(q, col[ref]) for q, _ in c.nets[net].pins
                      if q != ref and q in col]
            if others:
                s += (sum(others) / len(others) - col[ref]) * ox
        score[r] = s
    return max(rots, key=lambda r: (score[r], -r))


def initial_state(plan: Plan) -> State:
    c = plan.circuit
    col = plan.columns
    rot = {}
    main = main_part(plan)
    for ref in plan.skeleton:
        part = c.parts[ref]
        if part.kind == "two":
            rot[ref] = _series_rotation(plan, ref, col)
        elif part.kind == "connector" and len(plan.rotations[ref]) > 1:
            # A free connector faces the main part: pins right when left of
            # it; of the ways that do, the one with pin 1 on top.
            first = str(part.symbol.pins[0].get("designator", ""))
            want = RIGHT if col[ref] < col[main] else LEFT
            facing = [o for o in plan.rotations[ref]
                      if part.pin_offset(first, o)[2] == want]
            rot[ref] = (max(facing, key=lambda o: (_pin_one_up(part, o), -o))
                        if facing else plan.rotations[ref][0])
        else:
            rot[ref] = plan.rotations[ref][0]
    # Attachments first, so a column leaves room for what hangs off it.
    attached: dict[str, tuple[int, int, int]] = {}
    groups: dict[tuple[str, int, int], list[tuple[int, str]]] = {}
    rows: dict[str, int] = {}
    for ref in sorted(plan.attachments):
        att = plan.attachments[ref]
        host_ref, host_pin = plan.anchors[ref][0]
        host = c.parts[host_ref]
        hx, hy, facing = host.pin_offset(host_pin, rot[host_ref])
        if att.role == "decap" and host.kind == "active" and len(host.symbol.pins) >= 4:
            # An IC's decoupling capacitors stand in a row above it, each
            # with its own rail and ground symbols, as datasheets draw them.
            ext = _extent(plan, host_ref, rot[host_ref])
            n = rows.get(host_ref, 0)
            rows[host_ref] = n + 1
            attached[ref] = (0, ext[0] + 1 + 4 * n - hx // GRID, ext[3] + 6 - hy // GRID)
            continue
        groups.setdefault((host_ref, facing, att.lane_facing), []).append((hy, ref))
    for (host_ref, facing, lane_facing), members in groups.items():
        # A staircase: the part hanging below its line goes past the lines
        # under it, so the lower the pin, the nearer its part (and the other
        # way round for parts standing above their line).
        members.sort(reverse=lane_facing == DOWN)
        d, perp = DIRS[facing], DIRS[(facing + 1) % 4]
        for n, (_, ref) in enumerate(members):
            att = plan.attachments[ref]
            side = 0
            if facing in (UP, DOWN) and (lane_facing == UP) == (facing == UP):
                side = 3          # it would hang back over its host: step aside
            k = 2 + 4 * n
            attached[ref] = (0, k * d[0] + side * perp[0], k * d[1] + side * perp[1])

    by_col: dict[int, list[str]] = {}
    for ref in plan.skeleton:
        by_col.setdefault(col[ref], []).append(ref)
    extents = {ref: _extent(plan, ref, rot[ref]) for ref in plan.skeleton}
    reach_right: dict[str, int] = {}
    reach_left: dict[str, int] = {}
    for ref, (ai, ox_, oy_) in attached.items():
        host_ref, _ = plan.anchors[ref][ai]
        if ox_ > 0:
            reach_right[host_ref] = max(reach_right.get(host_ref, 0), ox_ + 3)
        elif ox_ < 0:
            reach_left[host_ref] = max(reach_left.get(host_ref, 0), -ox_ + 3)

    # x: each column after the last, wide enough for its parts and what
    # hangs off their pins.
    x_of: dict[int, int] = {}          # mils
    cursor = 0                         # cells
    for k in sorted(by_col):
        refs = by_col[k]
        left = min(extents[r][0] for r in refs)
        right = max(extents[r][2] for r in refs)
        cursor += max((reach_left.get(r, 0) for r in refs), default=0)
        x_of[k] = (cursor - left) * GRID
        cursor = cursor - left + right + 4 + max((reach_right.get(r, 0) for r in refs), default=0)

    # y: the main part at 0, then each part lined up with the pin it meets.
    y_of: dict[str, int] = {main: 0}
    order = [main]
    nbrs = _signal_neighbours(plan, ("signal",))
    while order:
        u = order.pop(0)
        for v in sorted(nbrs.get(u, ())):
            if v in y_of:
                continue
            y_of[v] = _aligned_y(plan, u, v, rot, y_of[u])
            order.append(v)
    for k in sorted(by_col):
        refs = by_col[k]
        placed = sorted((r for r in refs if r in y_of), key=lambda r: -y_of[r])
        free = [r for r in refs if r not in y_of]
        top = max((y_of[r] // GRID + extents[r][3] for r in placed), default=0)
        bottom = min((y_of[r] // GRID + extents[r][1] for r in placed), default=0)
        for r in sorted(free, key=lambda r: not _has_power(c, r)):
            if _has_power(c, r) or not placed:
                y_of[r] = (top - extents[r][1] + 4) * GRID
                top = y_of[r] // GRID + extents[r][3]
            else:
                y_of[r] = (bottom - extents[r][3] - 4) * GRID
                bottom = y_of[r] // GRID + extents[r][1]
        _spread(by_col[k], y_of, extents)
    skeleton = {r: (x_of[col[r]], y_of[r], rot[r]) for r in plan.skeleton}
    return State(skeleton, attached)


def _rails_in_order(c: Circuit, part: Part, orientation: int) -> int:
    """How well a part's pins sit for their nets at this orientation: a
    pin on a supply rail high (its symbol points up), on ground low."""
    nets = c.nets_of(part.ref)
    score = 0
    for p in part.pin_ends(0, 0, orientation):
        kind = c.nets[nets[p.number]].kind if p.number in nets else ""
        score += p.y if kind == "power" else -p.y if kind == "ground" else 0
    return score


def _pin_one_up(part: Part, orientation: int) -> int:
    """How many pins sit below pin 1, the lowest-numbered pin, at this
    orientation: a connector reads pin 1 at the top."""
    ends = part.pin_ends(0, 0, orientation)
    if not ends:
        return 0
    first = min(ends, key=lambda p: (len(p.number), p.number))
    return sum(1 for p in ends if p.y < first.y) - sum(1 for p in ends if p.y > first.y)


def _has_power(c: Circuit, ref: str) -> bool:
    return any(c.nets[n].kind == "power" for n in c.nets_of(ref).values())


def _aligned_y(plan: Plan, u: str, v: str, rot: dict, yu: int) -> int:
    """v's y so that its pin on a net shared with u is level with u's pin."""
    c = plan.circuit
    nu, nv = c.nets_of(u), c.nets_of(v)
    for pu, net in nu.items():
        if c.nets[net].kind != "signal":
            continue
        for pv, net_v in nv.items():
            if net_v != net:
                continue
            ux, uy, uo = c.parts[u].pin_offset(pu, rot[u])
            vx, vy, vo = c.parts[v].pin_offset(pv, rot[v])
            target = yu + uy
            if uo == UP:
                target += 3 * GRID
            elif uo == DOWN:
                target -= 3 * GRID
            return target - vy
    return yu


def _spread(refs: list[str], y_of: dict[str, int], extents: dict) -> None:
    """Push a column's parts apart, top to bottom, until none overlap."""
    order = sorted(refs, key=lambda r: -y_of[r])
    for a, b in zip(order, order[1:]):
        a_bottom = y_of[a] // GRID + extents[a][1]
        b_top = y_of[b] // GRID + extents[b][3]
        if b_top > a_bottom - 3:
            y_of[b] -= (b_top - (a_bottom - 3)) * GRID
